import sys
from datetime import datetime

GREETINGS = {
    "en": ("Good morning", "Good afternoon", "Good evening", "Hello"),
}


def greeting(lang, hour):
    morning, afternoon, evening, fallback = GREETINGS[lang]
    if 5 <= hour < 12:
        return morning
    if 12 <= hour < 18:
        return afternoon
    if 18 <= hour < 23:
        return evening
    return fallback


if __name__ == "__main__":
    print(greeting("en", datetime.now().hour))

import sys
from datetime import datetime

GREETINGS = {
    "en": ("Good morning", "Good afternoon", "Good evening", "Hello"),
    "jp": ("おはようございます", "こんにちは", "こんばんは", "やあ"),
}


def greeting(lang, hour):
    morning, afternoon, evening, fallback = GREETINGS[lang]
    if 5 <= hour < 12:
        return morning
    if 12 <= hour < 18:
        return afternoon
    if 18 <= hour < 23:
        return evening
    return fallback


if __name__ == "__main__":
    print(greeting("jp" if "jp" in sys.argv[1:] else "en", datetime.now().hour))
